"use client"

// From chatcn, chat, voice and agent UI for shadcn: https://chatcn.dev

import * as React from "react"
import { cn } from "@/lib/utils"

/** chatcn theme variables and utilities this file uses, light and dark. */
const CHATCN_CSS = ":root{--chatcn-bg:oklch(1 0 0);--chatcn-border:var(--chatcn-gray-400);--chatcn-fg:var(--chatcn-gray-1000);--chatcn-fg-faint:var(--chatcn-gray-700);--chatcn-fg-muted:var(--chatcn-gray-900);--chatcn-fg-subtle:var(--chatcn-gray-800);--chatcn-fill-active:var(--chatcn-gray-300);--chatcn-gray-1000:oklch(0.145 0 0);--chatcn-gray-300:oklch(0.930 0 0);--chatcn-gray-400:oklch(0.910 0 0);--chatcn-gray-700:oklch(0.700 0 0);--chatcn-gray-800:oklch(0.525 0 0);--chatcn-gray-900:oklch(0.440 0 0)}.dark{--chatcn-bg:oklch(0.145 0 0);--chatcn-border:var(--chatcn-gray-400);--chatcn-fg:var(--chatcn-gray-1000);--chatcn-fg-faint:var(--chatcn-gray-700);--chatcn-fg-muted:var(--chatcn-gray-900);--chatcn-fg-subtle:var(--chatcn-gray-800);--chatcn-fill-active:var(--chatcn-gray-300);--chatcn-gray-1000:oklch(0.970 0 0);--chatcn-gray-300:oklch(0.255 0 0);--chatcn-gray-400:oklch(0.285 0 0);--chatcn-gray-700:oklch(0.500 0 0);--chatcn-gray-800:oklch(0.620 0 0);--chatcn-gray-900:oklch(0.720 0 0)}"
if (typeof document !== "undefined" && !document.getElementById("chatcn-audio-visualizer")) {
  const style = document.createElement("style")
  style.id = "chatcn-audio-visualizer"
  style.textContent = CHATCN_CSS
  document.head.appendChild(style)
}

/* -------------------------------------------------------------------------------------------------
 * Types
 * -----------------------------------------------------------------------------------------------*/

export type AudioVisualizerVariant = "bars" | "radial" | "grid" | "line" | "dots"

/* -------------------------------------------------------------------------------------------------
 * Level and band sources
 *
 * Voice components take audio levels as plain values or as getters. A number re-renders the
 * component on every change, which is fine at 20 updates a second. A getter is read once per
 * animation frame and never re-renders anything, which is what a 60 fps meter wants.
 * -----------------------------------------------------------------------------------------------*/

/** A level from 0 to 1, or a function that returns the current one. */
type ChatcnLevel = number | (() => number)

/** Band levels from 0 to 1, lowest frequency first, or a function that fills `count` of them. */
type ChatcnBands = ArrayLike<number> | ((count: number) => ArrayLike<number>)

export type AudioVisualizerState = "idle" | "connecting" | "listening" | "thinking" | "speaking"

export interface AudioVisualizerProps extends Omit<React.ComponentProps<"div">, "children"> {
  /** Default `bars`. */
  variant?: AudioVisualizerVariant
  /** Overall level from 0 to 1, or a getter. Bands are synthesized from it when `bands` is absent. */
  level?: ChatcnLevel
  /** Band levels, lowest frequency first, or a getter such as `useChatcnAudioLevel().getBands`. */
  bands?: ChatcnBands
  /**
   * What the agent is doing. Audio drives listening and speaking; connecting sweeps a highlight
   * across, thinking breathes out from the centre, idle rests. Default `speaking`.
   */
  state?: AudioVisualizerState
  /** Bars, spokes, columns or dots. Defaults: bars 7, radial 48, grid 16, line 40, dots 9. */
  count?: number
  /** Force reduced motion on or off. Defaults to the user's setting. */
  reducedMotion?: boolean
  /** Accessible name. Defaults to "Audio: speaking" and so on. */
  label?: string
}

/* -------------------------------------------------------------------------------------------------
 * Reduced motion
 * -----------------------------------------------------------------------------------------------*/

const REDUCED = "(prefers-reduced-motion: reduce)"

/** True when the user asked for reduced motion. Updates live when the setting changes. */
function useChatcnPrefersReducedMotion() {
  const [reduced, setReduced] = React.useState(false)
  React.useEffect(() => {
    const query = window.matchMedia?.(REDUCED)
    if (!query) return
    const update = () => setReduced(query.matches)
    update()
    query.addEventListener("change", update)
    return () => query.removeEventListener("change", update)
  }, [])
  return reduced
}

const COUNTS: Record<AudioVisualizerVariant, number> = {
  bars: 7,
  radial: 48,
  grid: 16,
  line: 40,
  dots: 9,
}

/* -------------------------------------------------------------------------------------------------
 * Theme colors for canvas
 * -----------------------------------------------------------------------------------------------*/

/** Resolved theme colors as CSS strings the canvas understands. Alpha goes through `globalAlpha`. */
interface ChatcnVoiceColors {
  /** The canvas `color`, so `text-*` classes tint the drawing. Defaults to the foreground. */
  fg: string
  muted: string
  subtle: string
  faint: string
  border: string
  fill: string
  bg: string
}

/* -------------------------------------------------------------------------------------------------
 * useChatcnVoiceCanvas
 * -----------------------------------------------------------------------------------------------*/

interface ChatcnVoiceFrame {
  ctx: CanvasRenderingContext2D
  /** CSS pixels. The context is already scaled for the device pixel ratio. */
  width: number
  height: number
  dpr: number
  /** Seconds of animated time. Only advances while frames run, so nothing jumps on resume. */
  t: number
  /** Seconds since the previous frame, capped at 50 ms. */
  dt: number
  colors: ChatcnVoiceColors
  reducedMotion: boolean
}

/** Draws one frame. Return true to keep animating, false to sleep until `invalidate()`. */
type ChatcnVoiceDraw = (frame: ChatcnVoiceFrame) => boolean

interface UseChatcnVoiceCanvasOptions {
  /** Force reduced motion on or off. Defaults to the user's setting. */
  reducedMotion?: boolean
}

interface ChatcnVoiceCanvas {
  /** Attach to a `<canvas>`. Its CSS size is observed; the backing store follows it. */
  ref: (element: HTMLCanvasElement | null) => void
  /** Ask for a frame. Call after props change; the loop sleeps when the drawing settles. */
  invalidate: () => void
  reducedMotion: boolean
  /** False until the canvas has a 2D context. Render a fallback while false. */
  supported: boolean
}

function readColors(element: Element): ChatcnVoiceColors {
  const style = getComputedStyle(element)
  const v = (name: string, fallback: string) => style.getPropertyValue(name).trim() || fallback
  const fg = style.color || v("--chatcn-fg", "currentColor")
  return {
    fg,
    muted: v("--chatcn-fg-muted", fg),
    subtle: v("--chatcn-fg-subtle", fg),
    faint: v("--chatcn-fg-faint", fg),
    border: v("--chatcn-border", fg),
    fill: v("--chatcn-fill-active", fg),
    bg: v("--chatcn-bg", "transparent"),
  }
}

/**
 * A sleeping requestAnimationFrame loop for voice visuals. Handles device pixel ratio, resizes,
 * theme changes (colors are re-read from CSS, so dark mode and `text-*` classes just work), and
 * pauses while the canvas is off screen or the tab is hidden. The draw function decides when to
 * sleep, so a settled orb or a silent meter costs nothing.
 */
function useChatcnVoiceCanvas(
  draw: ChatcnVoiceDraw,
  options: UseChatcnVoiceCanvasOptions = {},
): ChatcnVoiceCanvas {
  const prefersReduced = useChatcnPrefersReducedMotion()
  const reducedMotion = options.reducedMotion ?? prefersReduced
  const [supported, setSupported] = React.useState(true)

  const drawRef = React.useRef(draw)
  drawRef.current = draw
  const reducedRef = React.useRef(reducedMotion)
  reducedRef.current = reducedMotion

  const s = React.useRef({
    canvas: null as HTMLCanvasElement | null,
    ctx: null as CanvasRenderingContext2D | null,
    colors: null as ChatcnVoiceColors | null,
    raf: 0,
    running: false,
    visible: true,
    last: 0,
    t: 0,
    cleanup: [] as (() => void)[],
  })

  const frame = React.useCallback((now: number) => {
    const st = s.current
    st.raf = 0
    const canvas = st.canvas
    const ctx = st.ctx
    if (!canvas || !ctx) {
      st.running = false
      return
    }
    const dt = st.last ? Math.min(0.05, Math.max(0, (now - st.last) / 1000)) : 1 / 60
    st.last = now
    st.t += dt

    const dpr = Math.min(3, window.devicePixelRatio || 1)
    const width = canvas.clientWidth
    const height = canvas.clientHeight
    const bw = Math.max(1, Math.round(width * dpr))
    const bh = Math.max(1, Math.round(height * dpr))
    if (canvas.width !== bw || canvas.height !== bh) {
      canvas.width = bw
      canvas.height = bh
    }
    if (!st.colors) st.colors = readColors(canvas)
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0)
    ctx.clearRect(0, 0, width, height)
    ctx.globalAlpha = 1

    const keep =
      width > 0 &&
      height > 0 &&
      drawRef.current({
        ctx,
        width,
        height,
        dpr,
        t: st.t,
        dt,
        colors: st.colors,
        reducedMotion: reducedRef.current,
      })

    if (keep && st.visible) {
      st.raf = requestAnimationFrame(frameRef.current)
    } else {
      st.running = false
      st.last = 0
    }
  }, [])
  const frameRef = React.useRef(frame)
  frameRef.current = frame

  const invalidate = React.useCallback(() => {
    const st = s.current
    if (st.running || !st.ctx) return
    st.running = true
    st.raf = requestAnimationFrame(frameRef.current)
  }, [])

  const ref = React.useCallback(
    (canvas: HTMLCanvasElement | null) => {
      const st = s.current
      for (const fn of st.cleanup) fn()
      st.cleanup = []
      if (st.raf) cancelAnimationFrame(st.raf)
      st.raf = 0
      st.running = false
      st.canvas = canvas
      st.ctx = null
      st.colors = null
      if (!canvas) return

      const ctx = canvas.getContext("2d")
      if (!ctx) {
        setSupported(false)
        return
      }
      st.ctx = ctx

      const refreshColors = () => {
        st.colors = null
        invalidate()
      }

      const resize = new ResizeObserver(() => invalidate())
      resize.observe(canvas)
      st.cleanup.push(() => resize.disconnect())

      const io = new IntersectionObserver((entries) => {
        const entry = entries[entries.length - 1]
        st.visible = entry ? entry.isIntersecting && !document.hidden : true
        if (st.visible) invalidate()
      })
      io.observe(canvas)
      st.cleanup.push(() => io.disconnect())

      const onVisibility = () => {
        st.visible = !document.hidden
        if (st.visible) invalidate()
      }
      document.addEventListener("visibilitychange", onVisibility)
      st.cleanup.push(() => document.removeEventListener("visibilitychange", onVisibility))

      // Theme switches toggle a class or attribute on <html>; the system theme fires a query.
      const mo = new MutationObserver(refreshColors)
      mo.observe(document.documentElement, {
        attributes: true,
        attributeFilter: ["class", "style", "data-theme"],
      })
      st.cleanup.push(() => mo.disconnect())
      const dark = window.matchMedia?.("(prefers-color-scheme: dark)")
      dark?.addEventListener("change", refreshColors)
      st.cleanup.push(() => dark?.removeEventListener("change", refreshColors))

      invalidate()
    },
    [invalidate],
  )

  // Reduced motion changes the drawing, so draw again.
  React.useEffect(() => {
    void reducedMotion
    invalidate()
  }, [reducedMotion, invalidate])

  React.useEffect(
    () => () => {
      const st = s.current
      for (const fn of st.cleanup) fn()
      if (st.raf) cancelAnimationFrame(st.raf)
    },
    [],
  )

  return { ref, invalidate, reducedMotion, supported }
}

/** Distance from the centre, 0 in the middle and 1 at either end. */
const dist = (i: number, count: number) =>
  count <= 1 ? 0 : Math.abs(i - (count - 1) / 2) / ((count - 1) / 2)

/** Still forms for reduced motion: each state keeps a distinct shape, nothing moves. */
function stillValues(state: AudioVisualizerState, count: number) {
  return Array.from({ length: count }, (_, i) => {
    const d = dist(i, count)
    if (state === "connecting") return i === Math.round((count - 1) / 2) ? 0.5 : 0
    if (state === "thinking") return 0.22 * (1 - d * 0.5)
    if (state === "listening") return 0.3 * (1 - d) ** 1.2
    if (state === "speaking") return 0.62 * (1 - d * 0.8) ** 1.4
    return 0
  })
}

const clamp01 = (value: number) => (Number.isFinite(value) ? Math.min(1, Math.max(0, value)) : 0)

/** Reads a band source, resampled to `count` bands. Undefined when there is no source. */
function readBands(bands: ChatcnBands | undefined, count: number): number[] | undefined {
  if (bands === undefined) return undefined
  const source = typeof bands === "function" ? bands(count) : bands
  if (source.length === 0) return undefined
  const out = new Array<number>(count)
  for (let i = 0; i < count; i++) {
    // Nearest band for upsampling, mean of the covered bands for downsampling.
    const from = Math.floor((i * source.length) / count)
    const to = Math.max(from + 1, Math.floor(((i + 1) * source.length) / count))
    let sum = 0
    for (let j = from; j < to; j++) sum += source[j] ?? 0
    out[i] = clamp01(sum / (to - from))
  }
  return out
}

/** Cheap deterministic noise in [-1, 1]: three incommensurate sines. Stable across renders. */
function wobble(t: number, seed: number) {
  return (
    Math.sin(t * 1.31 + seed * 7.13) * 0.5 +
    Math.sin(t * 2.17 + seed * 3.71) * 0.3 +
    Math.sin(t * 3.73 + seed * 1.37) * 0.2
  )
}

/**
 * Turns one level into `count` plausible band levels, for visualizers fed only a level. Speech
 * energy sits in the low and middle bands, so the shape leans there and drifts over time.
 */
function synthesizeBands(level: number, count: number, t: number): number[] {
  const out = new Array<number>(count)
  for (let i = 0; i < count; i++) {
    const x = count === 1 ? 0.5 : i / (count - 1)
    // A soft formant hump around the lower middle, plus a moving ripple.
    const hump = 0.45 + 0.55 * Math.exp(-(((x - 0.38) / 0.32) ** 2))
    const ripple = 0.72 + 0.28 * wobble(t * 2.4, i * 0.77 + 1)
    out[i] = clamp01(level * hump * ripple * 1.25)
  }
  return out
}

/** Reads a level source. Undefined reads as silence. */
function readLevel(level: ChatcnLevel | undefined): number {
  if (level === undefined) return 0
  return clamp01(typeof level === "function" ? level() : level)
}

/** Blends each value with its neighbours and leans on the centre, so energy swells as one shape. */
function smooth(values: number[], count: number): number[] {
  return values.map((v, i) => {
    const a = values[i - 1] ?? v
    const b = values[i + 1] ?? v
    return (a * 0.25 + v * 0.5 + b * 0.25) * (1 - 0.3 * dist(i, count) ** 2) * 1.1
  })
}

/* -------------------------------------------------------------------------------------------------
 * Values
 *
 * Every variant draws one array of values from 0 to 1, laid out so the lowest band sits in the
 * middle and higher bands spread outward. Voices carry most energy low, so the shape swells from
 * the centre like speech instead of leaning to one side like a music equalizer.
 * -----------------------------------------------------------------------------------------------*/

/** Spreads bands (lowest first) out from the centre: position i gets the band at its distance. */
function centreOut(bands: number[], count: number): number[] {
  const out = new Array<number>(count)
  const half = (count - 1) / 2
  for (let i = 0; i < count; i++) {
    const d = Math.abs(i - half) / Math.max(1, half)
    const idx = Math.min(bands.length - 1, Math.round(d * (bands.length - 1)))
    out[i] = bands[idx] ?? 0
  }
  return out
}

/** State motion without audio. Loops in `circular` variants wrap around instead of bouncing. */
function stateValues(state: AudioVisualizerState, count: number, t: number, circular: boolean) {
  const out = new Array<number>(count).fill(0)
  if (state === "connecting") {
    // A soft highlight travels across and back, or around, once every 1.6 s.
    const period = 1.6
    const u = (t % period) / period
    const pos = circular ? u * count : (0.5 - 0.5 * Math.cos(u * Math.PI * 2)) * (count - 1)
    const width = Math.max(1, count * (circular ? 0.08 : 0.16))
    for (let i = 0; i < count; i++) {
      let d = Math.abs(i - pos)
      if (circular) d = Math.min(d, count - d)
      out[i] = 0.55 * Math.exp(-((d / width) ** 2))
    }
  } else if (state === "thinking") {
    // Breathing out from the centre, one wave every 1.8 s.
    for (let i = 0; i < count; i++) {
      const d = circular ? 0.5 : dist(i, count)
      const wave = 0.5 + 0.5 * Math.sin((t * Math.PI * 2) / 1.8 - d * 2.2)
      out[i] = (0.12 + 0.22 * wave) * (1 - d * 0.35)
    }
  }
  return out
}

const clamp = (v: number) => Math.min(1, Math.max(0, v))

/** Moves `current` toward `target` with an exponential approach: critically damped, no bounce. */
function approach(current: number, target: number, rate: number, dt: number) {
  return current + (target - current) * (1 - Math.exp(-rate * dt))
}

/* -------------------------------------------------------------------------------------------------
 * Variants
 * -----------------------------------------------------------------------------------------------*/

interface Paint {
  ctx: CanvasRenderingContext2D
  width: number
  height: number
  values: number[]
  fg: string
  rest: string
}

/** Rest is faint ink; energy ramps to full ink, so quiet parts recede without a second color. */
const inkAlpha = (v: number) => 0.28 + 0.72 * clamp(v * 2.4)

function pill(ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number) {
  if (typeof ctx.roundRect === "function") ctx.roundRect(x, y, w, h, Math.min(w, h) / 2)
  else ctx.rect(x, y, w, h)
}

function paintBars({ ctx, width, height, values, fg }: Paint) {
  const n = values.length
  const gapRatio = 0.6
  const w = Math.min(height * 0.3, width / (n + (n - 1) * gapRatio))
  const gap = w * gapRatio
  const x0 = (width - (n * w + (n - 1) * gap)) / 2
  ctx.fillStyle = fg
  for (let i = 0; i < n; i++) {
    const v = values[i] ?? 0
    const h = Math.max(w, v * height)
    ctx.globalAlpha = inkAlpha(v)
    ctx.beginPath()
    pill(ctx, x0 + i * (w + gap), (height - h) / 2, w, h)
    ctx.fill()
  }
}

function paintRadial({ ctx, width, height, values, fg }: Paint) {
  const n = values.length
  const cx = width / 2
  const cy = height / 2
  const outer = Math.min(width, height) / 2 - 2
  const inner = outer * 0.48
  const lineWidth = Math.max(1.25, Math.min(3, ((Math.PI * 2 * inner) / n) * 0.42))
  ctx.strokeStyle = fg
  ctx.lineCap = "round"
  ctx.lineWidth = lineWidth
  for (let i = 0; i < n; i++) {
    const v = values[i] ?? 0
    const a = (i / n) * Math.PI * 2 - Math.PI / 2
    const len = lineWidth * 0.5 + v * (outer - inner - lineWidth)
    ctx.globalAlpha = inkAlpha(v)
    ctx.beginPath()
    ctx.moveTo(cx + Math.cos(a) * inner, cy + Math.sin(a) * inner)
    ctx.lineTo(cx + Math.cos(a) * (inner + len), cy + Math.sin(a) * (inner + len))
    ctx.stroke()
  }
}

function paintGrid({ ctx, width, height, values, fg, rest }: Paint) {
  const cols = values.length
  const gap = 2
  const cell = Math.max(2, (width - (cols - 1) * gap) / cols)
  // Odd row count, so the middle row is the baseline and energy grows up and down from it.
  let rows = Math.max(3, Math.floor((height + gap) / (cell + gap)))
  if (rows % 2 === 0) rows -= 1
  const x0 = (width - (cols * cell + (cols - 1) * gap)) / 2
  const y0 = (height - (rows * cell + (rows - 1) * gap)) / 2
  const half = (rows - 1) / 2
  const r = Math.min(2, cell / 3)
  for (let c = 0; c < cols; c++) {
    const lit = (values[c] ?? 0) * (half + 1)
    for (let row = 0; row < rows; row++) {
      const d = Math.abs(row - half)
      // The cell straddling the level lights partially, so the meter moves smoothly.
      const amount = clamp(lit - d)
      const x = x0 + c * (cell + gap)
      const y = y0 + row * (cell + gap)
      ctx.globalAlpha = 1
      ctx.fillStyle = rest
      ctx.beginPath()
      if (typeof ctx.roundRect === "function") ctx.roundRect(x, y, cell, cell, r)
      else ctx.rect(x, y, cell, cell)
      ctx.fill()
      if (amount > 0) {
        ctx.globalAlpha = amount
        ctx.fillStyle = fg
        ctx.fill()
      }
    }
  }
}

function paintLine({ ctx, width, height, values, fg }: Paint) {
  const n = values.length
  const mid = height / 2
  const amp = height / 2 - 2
  const step = width / Math.max(1, n - 1)
  // Tapered at both ends, so the curve leaves and returns to the baseline.
  const ys = values.map((v, i) => v * amp * Math.sin((Math.PI * i) / Math.max(1, n - 1)) ** 0.8)
  ctx.strokeStyle = fg
  ctx.lineWidth = 1.5
  ctx.lineJoin = "round"
  ctx.lineCap = "round"
  for (const dir of [-1, 1]) {
    ctx.globalAlpha = dir < 0 ? 1 : 0.4
    ctx.beginPath()
    ctx.moveTo(0, mid + dir * (ys[0] ?? 0))
    for (let i = 1; i < n - 1; i++) {
      const x = i * step
      const nx = (i + 1) * step
      ctx.quadraticCurveTo(
        x,
        mid + dir * (ys[i] ?? 0),
        (x + nx) / 2,
        mid + dir * (((ys[i] ?? 0) + (ys[i + 1] ?? 0)) / 2),
      )
    }
    ctx.lineTo(width, mid + dir * (ys[n - 1] ?? 0))
    ctx.stroke()
  }
}

function paintDots({ ctx, width, height, values, fg }: Paint) {
  const n = values.length
  const pitch = width / n
  const rMax = Math.min(pitch * 0.42, height / 2)
  const rMin = Math.max(1.5, rMax * 0.28)
  ctx.fillStyle = fg
  for (let i = 0; i < n; i++) {
    const v = values[i] ?? 0
    ctx.globalAlpha = inkAlpha(v)
    ctx.beginPath()
    ctx.arc(pitch * (i + 0.5), height / 2, rMin + clamp(v * 1.3) * (rMax - rMin), 0, Math.PI * 2)
    ctx.fill()
  }
}

const PAINT: Record<AudioVisualizerVariant, (p: Paint) => void> = {
  bars: paintBars,
  radial: paintRadial,
  grid: paintGrid,
  line: paintLine,
  dots: paintDots,
}

const STATE_LABELS: Record<AudioVisualizerState, string> = {
  idle: "idle",
  connecting: "connecting",
  listening: "listening",
  thinking: "thinking",
  speaking: "speaking",
}

const SIZES: Record<AudioVisualizerVariant, string> = {
  bars: "h-16 w-40",
  radial: "size-32",
  grid: "h-16 w-48",
  line: "h-16 w-48",
  dots: "h-12 w-40",
}

/* -------------------------------------------------------------------------------------------------
 * AudioVisualizer
 * -----------------------------------------------------------------------------------------------*/

/**
 * Agent audio in five forms: bars, radial, grid, line and dots. Feed it bands from
 * `useChatcnAudioLevel`, or just a level and it synthesizes a speech-shaped spectrum. Without audio,
 * the state still shows: a sweep while connecting, a slow breath while thinking.
 */
export function AudioVisualizer({
  variant = "bars",
  level,
  bands,
  state = "speaking",
  count: countProp,
  reducedMotion: reducedProp,
  label,
  className,
  ...props
}: AudioVisualizerProps) {
  const prefersReduced = useChatcnPrefersReducedMotion()
  const reducedMotion = reducedProp ?? prefersReduced
  const count = Math.max(1, Math.round(countProp ?? COUNTS[variant]))

  const props$ = React.useRef({ variant, level, bands, state, count })
  props$.current = { variant, level, bands, state, count }
  const values = React.useRef<number[]>([])

  const canvas = useChatcnVoiceCanvas(
    ({ ctx, width, height, dt, t, colors, reducedMotion: reduced }) => {
      const p = props$.current
      const circular = p.variant === "radial"
      const n = p.count
      if (values.current.length !== n) values.current = new Array<number>(n).fill(0)

      let target: number[]
      if (reduced) {
        target = stillValues(p.state, n)
      } else {
        const audio = p.state === "listening" || p.state === "speaking"
        // Radial wraps a full turn, so its spectrum is mirrored around the circle.
        const bandCount = circular ? Math.ceil(n / 2) : Math.ceil(n / 2) + 1
        let spectrum: number[] | undefined
        if (audio) {
          spectrum = readBands(p.bands, bandCount)
          if (!spectrum) spectrum = synthesizeBands(readLevel(p.level), bandCount, t)
        }
        const laid = spectrum
          ? circular
            ? Array.from({ length: n }, (_, i) => {
                // Folded twice: lows at the top and bottom, highs at the sides, so it stays balanced.
                const d = 1 - Math.abs(1 - (2 * Math.min(i, n - i)) / (n / 2))
                return spectrum?.[Math.min(bandCount - 1, Math.round(d * (bandCount - 1)))] ?? 0
              })
            : smooth(centreOut(spectrum, n), n)
          : new Array<number>(n).fill(0)
        const motion = stateValues(p.state, n, t, circular)
        // Speech rarely nears full scale; lift it so a normal voice fills most of the space.
        target = laid.map((v, i) => Math.max(clamp(v * 1.4) ** 0.8, motion[i] ?? 0))
      }

      // Fast rise, slower fall, per value: syllables land crisply and decay naturally.
      const cur = values.current
      let settled = true
      for (let i = 0; i < n; i++) {
        const goal = target[i] ?? 0
        const prev = cur[i] ?? 0
        const next = reduced ? goal : approach(prev, goal, goal > prev ? 24 : 8, dt)
        cur[i] = next
        if (Math.abs(next - goal) > 0.002) settled = false
      }

      PAINT[p.variant]({ ctx, width, height, values: cur, fg: colors.fg, rest: colors.fill })
      ctx.globalAlpha = 1

      if (reduced) return false
      return !(p.state === "idle" && settled)
    },
    { reducedMotion },
  )

  React.useEffect(() => {
    void [variant, state, count, level, bands]
    canvas.invalidate()
  }, [variant, state, count, level, bands, canvas.invalidate])

  return (
    <div
      role="img"
      aria-label={label ?? `Audio: ${STATE_LABELS[state]}`}
      data-slot="audio-visualizer"
      data-variant={variant}
      data-visualizer-state={state}
      className={cn("text-(color:--chatcn-fg) relative shrink-0", SIZES[variant], className)}
      {...props}
    >
      {/* Children of role="img" are presentational, so the canvas needs no aria-hidden. */}
      <canvas ref={canvas.ref} className="absolute inset-0 size-full" />
    </div>
  )
}

